/* Service worker for Italian B1 (PLIDA + CILS). Generated by scripts/pwa_offline.py: do not edit by hand. */
const VERSION = '035faa7079aa';
const SHELL_CACHE = 'shell-' + VERSION;
const AUDIO_CACHE = 'audio-v1';                 // content-addressed files: kept across versions
const SHELL = ["index.html", "cils.html", "manifest.json", "audio-index.json", "favicon.ico", "icon-192.png", "icon-512.png", "icon-maskable-512.png", "apple-touch-icon.png"];
const PAGES = ['index.html', 'cils.html'];

self.addEventListener('install', (event) => {
  // all or nothing: a half-cached shell never becomes active
  event.waitUntil(caches.open(SHELL_CACHE).then((cache) => Promise.all(SHELL.map((url) =>
    fetch(new Request(url, {cache: 'reload'})).then((res) => {
      if (!res.ok) throw new Error('precache ' + url + ' ' + res.status);
      return cache.put(url, res);
    })))));
});

self.addEventListener('activate', (event) => {
  // only old app shells go; the audio cache and the pages' saved progress stay
  event.waitUntil(caches.keys().then((keys) => Promise.all(keys
    .filter((k) => k.startsWith('shell-') && k !== SHELL_CACHE)
    .map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

function rel(url) {
  const base = new URL(self.registration.scope);
  return url.pathname.startsWith(base.pathname) ? url.pathname.slice(base.pathname.length) : null;
}

function fromShell(name) {
  return caches.open(SHELL_CACHE).then((c) => c.match(name, {ignoreSearch: true}));
}

async function page(req, path) {
  const name = PAGES.includes(path) ? path : 'index.html';
  const known = PAGES.includes(path) || path === '';
  if (known) {
    const hit = await fromShell(name);
    if (hit) return hit;
  }
  try {
    return await fetch(req);
  } catch (e) {
    return (await fromShell(name)) || Response.error();
  }
}

async function ranged(req, res) {
  const range = req.headers.get('range');
  if (!range) return res;
  const buf = await res.arrayBuffer(), size = buf.byteLength;
  const m = /bytes=(\d*)-(\d*)/.exec(range);
  let start = 0, end = size - 1;
  if (m && m[1]) { start = +m[1]; if (m[2]) end = Math.min(+m[2], size - 1); }
  else if (m && m[2]) start = Math.max(size - +m[2], 0);
  if (start >= size) return new Response(null, {status: 416, headers: {'Content-Range': 'bytes */' + size}});
  return new Response(buf.slice(start, end + 1), {status: 206, headers: {
    'Content-Type': res.headers.get('Content-Type') || 'audio/mpeg', 'Accept-Ranges': 'bytes',
    'Content-Range': 'bytes ' + start + '-' + end + '/' + size, 'Content-Length': String(end - start + 1)}});
}

async function audio(req, url) {
  const cache = await caches.open(AUDIO_CACHE);
  let res = await cache.match(url.pathname);
  if (!res) {
    res = await fetch(url.pathname);            // the whole file, never a partial one, goes into the cache
    if (res.ok) await cache.put(url.pathname, res.clone());
    else return res;
  }
  return ranged(req, res);
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const path = rel(url);
  if (path === null) return;
  if (req.mode === 'navigate') return event.respondWith(page(req, path));
  if (path.startsWith('audio/') && path.endsWith('.mp3')) return event.respondWith(audio(req, url));
  if (SHELL.includes(path)) {
    return event.respondWith(fromShell(path).then((hit) => hit || fetch(req)));
  }
  event.respondWith(fetch(req).catch(() => caches.match(req).then((hit) => hit || Response.error())));
});
